var o=[{title:`Objetivos de resultado e de processo`,text:`Um objetivo de resultado indica o que quer alcançar, por exemplo oito flexões controladas ou caminhar 30 minutos sem parar. Um objetivo de processo indica o comportamento que o leva lá, como duas sessões de força por semana. Os resultados motivam, e os processos dão-lhe o plano diário.`},{title:`Objetivos SMART`,text:`Um objetivo prático é específico, mensurável, atingível, relevante e com prazo (SMART). “Ficar em forma” é demasiado vago. Experimente “fazer dois treinos de corpo inteiro de 30 minutos por semana durante seis semanas e aumentar a minha caminhada contínua confortável de 10 para 20 minutos”. A sua meta exata deve depender da sua capacidade atual, da saúde e do horário.`},{title:`Defina um ponto de partida`,text:`Antes de começar, registe algo que consiga repetir: a variação de flexão que faz com boa forma, a carga e as repetições num movimento familiar ou o tempo que consegue caminhar com conforto. Compare o semelhante com o semelhante. Muitos principiantes melhoram bastante nas primeiras semanas, mas as alterações de força e de composição corporal variam muito, por isso ninguém pode prometer com fiabilidade um ritmo específico de ganho muscular ou perda de gordura.`},{title:`Preveja interrupções`,text:`Decida uma versão mínima do objetivo para semanas ocupadas, como um treino mais curto no lugar de uma sessão falhada. Não defina várias metas agressivas ao mesmo tempo. Se um objetivo for tão difícil que exija uma velocidade pouco segura ou demasiado volume de treino, reduza-o.`},{title:`Reveja e ajuste`,text:`Reavalie cerca de cada quatro a oito semanas. Se cumpre o plano mas o progresso é lento, mude uma variável de treino ou dê a si próprio mais tempo. Se falha sessões repetidamente, corrija o horário antes de acrescentar exercícios.`},{title:`Usar o TrainUp`,text:`O seu objetivo, os dias de treino e a duração da sessão estão no Perfil. Durante cada treino assinala as séries e regista as repetições, e depois avalia o esforço. O Histórico mostra então se o seu objetivo de processo está a acontecer semana a semana.`}];var s=[{label:`CDC: começar e manter a atividade`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:o,sources:s};export{t as default,o as sections,s as sources};